import {esc} from '../../ui/format.js';
export function experimentsView(experiments=[],error=''){
 return `<section class="panel"><h2>Experimente salvate</h2><p>Snapshot + setari + seeds + versiune motor + rezultate. Salvare automata in IndexedDB pe acest browser, inclusiv in modul Docker; nu este arhiva partajata pe server. Exporta pentru backup.</p>${error?`<div class="notice">${esc(error)}</div>`:''}<button data-action="refresh-experiments">Actualizeaza lista</button><div class="tablewrap"><table><thead><tr><th>Experiment</th><th>Data / versiune</th><th>Replicari</th><th>Actiuni</th></tr></thead><tbody>${experiments.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.timestamp)}<br>${esc(e.engineVersion)} / ${esc(e.analysisVersion)}</td><td>${e.seeds.length}</td><td><button data-experiment-view="${esc(e.id)}">Deschide</button><button data-experiment-rerun="${esc(e.id)}">Re-ruleaza snapshot</button><button data-experiment-export="${esc(e.id)}">Export JSON</button></td></tr>`).join('')||'<tr><td colspan="4">Niciun experiment salvat.</td></tr>'}</tbody></table></div></section>`;
}
